To create a simple YAML parser in Go, you can use the following code. This parser handles basic YAML structures without requiring any external libraries. It supports nested maps and lists, and it can parse simple scalar values.

```go
package main

import (
	"fmt"
	"strings"
)

type YAMLNode map[string]interface{}

func ParseYAML(input string) YAMLNode {
	lines := strings.Split(input, "\n")
	return parseYAMLLines(lines)
}

func parseYAMLLines(lines []string) YAMLNode {
	root := YAMLNode{}
	currentNode := root
	currentIndent := 0

	for _, line := range lines {
		trimmedLine := strings.TrimSpace(line)
		if trimmedLine == "" {
			continue
		}

		indent := getIndent(line)
		if indent > currentIndent {
			currentNode = currentNode[strings.TrimRight(line[:indent], " ")](YAMLNode{})
		} else if indent < currentIndent {
			for indent < currentIndent {
				currentNode = currentNode[strings.TrimRight(line[:indent], " ")](YAMLNode{})
				currentIndent--
			}
		}

		keyValue := strings.SplitN(trimmedLine, ":", 2)
		if len(keyValue) != 2 {
			continue
		}

		key := strings.TrimSpace(keyValue[0])
		value := parseSimpleValue(strings.TrimSpace(keyValue[1]))
		currentNode[key] = value
	}

	return root
}

func getIndent(s string) int {
	return len(s) - len(strings.TrimLeft(s, " "))
}

func parseSimpleValue(value string) interface{} {
	if value == "true" {
		return true
	} else if value == "false" {
		return false
	} else if intValue, err := strconv.Atoi(value); err == nil {
		return intValue
	} else if floatValue, err := strconv.ParseFloat(value, 64); err == nil {
		return floatValue
	}
	return value
}

func main() {
	yaml := `
name: John Doe
age: 30
is_student: false
address:
  street: 123 Main St
  city: Anytown
`
	node := ParseYAML(yaml)
	fmt.Printf("%v\n", node)
}
```

This code provides a basic YAML parser that can handle nested structures and simple scalar values. It uses indentation to determine the structure of the YAML document.

